package com.fiuu.xdkandroid.ui

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.graphics.ImageBitmap
import org.jetbrains.compose.resources.decodeToImageBitmap
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/**
 * Raster images embedded as bytes so the SDK stays self-contained on iOS.
 *
 * The iOS XCFramework ships without `compose-resources` (zero-resource architecture), so any
 * `painterResource(Res.drawable.*)` call throws `MissingResourceException` at runtime there.
 * Vector art belongs in [AppIcons]; raster assets that can't be vectorised go here instead.
 */
@OptIn(ExperimentalEncodingApi::class)
object EmbeddedImages {

    /** `powered_by_molpay.webp` (168x37). */
    private const val POWERED_BY_MOLPAY_WEBP =
        ""

    fun poweredByMolpay(): ImageBitmap =
        Base64.decode(POWERED_BY_MOLPAY_WEBP).decodeToImageBitmap()
}

@Composable
fun rememberPoweredByMolpay(): ImageBitmap = remember { EmbeddedImages.poweredByMolpay() }
